export interface NavItem {
  label: string;
  href: string;
  order?: number;
}

export interface NavSection {
  title: string;
  items: NavItem[];
}

// Command reference pages are generated by cmd/gendocs (see .github/workflows/docs.yml),
// so the Commands section is built from the files that exist instead of a hand-kept list.
const commandFiles = Object.keys(import.meta.glob('../content/docs/commands/*.md'));

const commandOrder = [
  'grepai', 'init', 'index', 'watch', 'search', 'trace', 'refs', 'rpg', 'status', 'stats',
  'workspace', 'agent-setup', 'mcp-serve', 'completion', 'update', 'version',
];
const subcommandOrder = [
  'callers', 'callees', 'readers', 'writers', 'graph', 'search', 'fetch', 'explore',
  'list', 'show', 'status', 'create', 'add', 'remove', 'delete',
];

function commandItems(): NavItem[] {
  const rank = (list: string[], value: string | undefined) => {
    if (value === undefined) return -1;
    const index = list.indexOf(value);
    return index === -1 ? list.length : index;
  };

  return commandFiles
    .map((file) => file.split('/').pop()!.replace(/\.md$/, ''))
    .map((slug) => {
      const [, top = 'grepai', sub] = slug === 'grepai' ? [] : slug.split('_');
      return { slug, top: slug === 'grepai' ? 'grepai' : top, sub };
    })
    .sort((a, b) =>
      rank(commandOrder, a.top) - rank(commandOrder, b.top) ||
      a.top.localeCompare(b.top) ||
      rank(subcommandOrder, a.sub) - rank(subcommandOrder, b.sub) ||
      (a.sub ?? '').localeCompare(b.sub ?? '')
    )
    .map(({ slug }, index) => ({
      label: slug.replace(/_/g, ' '),
      href: `/grepai/commands/${slug}/`,
      order: index + 1,
    }));
}

